{
  "id": "attendance_allowance",
  "benefit": "attendance_allowance",
  "name": "Attendance Allowance",
  "version": "2026-27",
  "jurisdiction": ["England", "Wales"],
  "sources": [
    {
      "url": "https://www.gov.uk/attendance-allowance/eligibility",
      "title": "Attendance Allowance - Eligibility (GOV.UK)",
      "retrieved": "2026-10-27"
    },
    {
      "url": "https://www.gov.uk/attendance-allowance",
      "title": "Attendance Allowance (GOV.UK)",
      "retrieved": "2026-10-27"
    }
  ],
  "clauses": [
    {
      "id": "AA-1",
      "text": "Must have reached State Pension age.",
      "source_url": "https://www.gov.uk/attendance-allowance/eligibility"
    },
    {
      "id": "AA-2",
      "text": "Must have a physical or mental disability or health condition severe enough to need help with personal care or supervision.",
      "source_url": "https://www.gov.uk/attendance-allowance/eligibility"
    },
    {
      "id": "AA-3",
      "text": "Must have needed that help for at least 6 months.",
      "source_url": "https://www.gov.uk/attendance-allowance/eligibility"
    },
    {
      "id": "AA-4",
      "text": "Must have been in Great Britain for at least 2 of the last 3 years.",
      "source_url": "https://www.gov.uk/attendance-allowance/eligibility"
    },
    {
      "id": "AA-5",
      "text": "Cannot get Attendance Allowance if already receiving Disability Living Allowance, Personal Independence Payment, or Adult Disability Payment.",
      "source_url": "https://www.gov.uk/attendance-allowance/eligibility"
    },
    {
      "id": "AA-6",
      "text": "Paid at £76.70/week (lower rate) or £114.60/week (higher rate); higher rate when help needed both day and night.",
      "source_url": "https://www.gov.uk/attendance-allowance"
    },
    {
      "id": "AA-7",
      "text": "Scheme covers England and Wales; people in Scotland apply for Pension Age Disability Payment.",
      "source_url": "https://www.gov.uk/attendance-allowance"
    }
  ],
  "derived": [],
  "eligibility": {
    "all": [
      {
        "field": "age_years",
        "op": ">=",
        "value": { "field": "state_pension_age" },
        "clause": "AA-1"
      },
      {
        "field": "needs_care_help",
        "op": "==",
        "value": true,
        "clause": "AA-2"
      },
      {
        "field": "care_need_months",
        "op": ">=",
        "value": 6,
        "clause": "AA-3"
      },
      {
        "field": "in_gb_2_of_last_3_years",
        "op": "==",
        "value": true,
        "clause": "AA-4"
      },
      {
        "field": "receives_dla_or_pip",
        "op": "==",
        "value": false,
        "clause": "AA-5"
      },
      {
        "field": "country",
        "op": "in",
        "value": ["England", "Wales"],
        "clause": "AA-7"
      }
    ]
  },
  "amount": {
    "expr": {
      "if": {
        "field": "care_day_and_night",
        "op": "==",
        "value": true,
        "clause": "AA-6"
      },
      "then": { "const": 114.60 },
      "else": { "const": 76.70 }
    },
    "unit": "weekly",
    "clause": "AA-6",
    "min_if_unknown": 76.70
  },
  "questions": {
    "age_years": "What is your date of birth? (used to calculate your age)",
    "state_pension_age": "What is your date of birth? (used to determine your State Pension age)",
    "needs_care_help": "Do you need help with personal care or supervision because of a disability or health condition?",
    "care_need_months": "For how many months have you needed this help?",
    "in_gb_2_of_last_3_years": "Have you been in Great Britain for at least 2 of the last 3 years?",
    "receives_dla_or_pip": "Are you currently receiving Disability Living Allowance, Personal Independence Payment, or Adult Disability Payment?",
    "country": "In which country do you live? (England, Wales, Scotland, or Northern Ireland)"
  },
  "already_receiving_field": "receives_dla_or_pip",
  "notes": "Attendance Allowance is for people in England and Wales who have reached State Pension age and need care help. Higher rate paid if help needed both day and night."
}
